import{_ as a,o as e,c as s,a3 as r}from"./chunks/framework.BFeCKmyl.js";const m=JSON.parse('{"title":"Painel fixo do processo","description":"","frontmatter":{"title":"Painel fixo do processo","id":"eproc-painel-fixo-processo","plataforma":"eproc","grupo":"Painel do processo","plano":"free","desde":"1.0.2","padrao":"ligado"},"headers":[],"relativePath":"funcionalidades/eproc-painel-fixo-processo.md","filePath":"funcionalidades/eproc-painel-fixo-processo.md"}'),i={name:"funcionalidades/eproc-painel-fixo-processo.md"};function n(l,o,d,t,c,p){return e(),s("div",null,o[0]||(o[0]=[r('<h1 id="painel-fixo-do-processo" tabindex="-1">Painel fixo do processo <a class="header-anchor" href="#painel-fixo-do-processo" aria-label="Permalink to &quot;Painel fixo do processo&quot;">​</a></h1><h2 id="o-que-faz" tabindex="-1">O que faz <a class="header-anchor" href="#o-que-faz" aria-label="Permalink to &quot;O que faz&quot;">​</a></h2><p>Mostra, num painel sempre visível, um resumo do processo: número, classe, assuntos, partes com CPF/CNPJ, advogados com OAB e os campos de Informações Adicionais que você escolher. Cada dado pode ser copiado com um clique, e o painel se atualiza sozinho quando a página muda.</p><h2 id="onde-aparece" tabindex="-1">Onde aparece <a class="header-anchor" href="#onde-aparece" aria-label="Permalink to &quot;Onde aparece&quot;">​</a></h2><p><strong>eproc</strong>, página do processo, cadastro de minuta e página de intimação. Por padrão, o painel fica preso junto ao menu lateral, sob o título &quot;Resumo do Processo&quot;.</p><h2 id="passo-a-passo" tabindex="-1">Passo a passo <a class="header-anchor" href="#passo-a-passo" aria-label="Permalink to &quot;Passo a passo&quot;">​</a></h2><ol><li>Abra um processo. O painel aparece ao lado do menu lateral.</li><li>Clique num dado (número, CPF, CNPJ, OAB, nome etc.) para copiá-lo.</li><li>Recolha ou expanda cada seção do painel pelo título dela. A escolha é lembrada entre processos.</li><li>Para escolher os campos de Informações Adicionais exibidos, abra a seção Informações Adicionais da página e use o botão <strong>+i</strong> ao lado de cada campo (&quot;Adicionar ao painel fixo do processo&quot;). Clique de novo para remover.</li><li>Para soltar o painel, desafixe-o: ele passa a flutuar e pode ser arrastado e redimensionado. A posição e o tamanho são lembrados.</li><li>Se o painel for recolhido ou ficar oculto, use o botão circular &quot;Mostrar painel do processo&quot; para trazê-lo de volta.</li></ol><p>Outros sinais do painel:</p><ul><li>Os assuntos ganham um selo de validado ou não validado. O selo de não validado abre a retificação de assuntos.</li><li>As partes ativas no Domicílio Judicial Eletrônico exibem o selo do DJE, com os prazos no balão.</li><li>O painel segue o tema claro ou escuro escolhido nas configurações do eploc.</li></ul><h2 id="configuracoes-e-opcoes" tabindex="-1">Configurações e opções <a class="header-anchor" href="#configuracoes-e-opcoes" aria-label="Permalink to &quot;Configurações e opções&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Opção</th><th>Padrão</th><th>Efeito</th></tr></thead><tbody><tr><td>Carregar automaticamente os campos de Informações Adicionais exibidos no painel que o eproc só carrega sob demanda (contadores, chave do processo)</td><td>desligada</td><td>Desligada, esses campos mostram um link &quot;carregar&quot; no painel. Ligada, são carregados ao abrir o processo.</td></tr></tbody></table><p>Para ocultar o número do processo no painel quando ele já aparece no menu superior, veja <a href="./eproc-numero-processo-navbar">Número do processo no menu superior</a>.</p><h2 id="observacoes" tabindex="-1">Observações <a class="header-anchor" href="#observacoes" aria-label="Permalink to &quot;Observações&quot;">​</a></h2><ul><li>Preso ao menu lateral, o painel se oculta quando o menu é recolhido ou quando você usa a busca do menu. O botão circular o reexibe até o menu voltar a abrir ou a página recarregar.</li><li>Campos de Informações Adicionais sem valor exibível não oferecem o botão <strong>+i</strong>.</li><li>A posição e o tamanho do painel solto ficam guardados no navegador, para cada endereço do eproc, e não entram no backup.</li></ul>',14)]))}const f=a(i,[["render",n]]);export{m as __pageData,f as default};
